import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import {
  MathError,
  curveParamsFromTarget,
  graduationQuote,
  poolQuoteBuy,
  poolQuoteSell,
  poolSupply,
  quoteBuy,
  quoteInForTokensOut,
  quoteSell,
  splitFee,
  type FeeRates,
  type PoolFeeRates,
  type PoolReserves,
  type Reserves,
} from "../src/math.ts";

/**
 * Replays the golden vectors generated by the Rust crate. Every case must
 * produce the same amounts, or refuse with the same error, as the code the
 * on-chain programs run.
 */

type Outcome<T> = { ok: T } | { err: string };
type RawReserves = Record<keyof Reserves, string>;

interface Vectors {
  buy: {
    reserves: RawReserves;
    rates: FeeRates;
    maxQuoteIn: string;
    result: Outcome<{
      quoteToCurve: string;
      platformFee: string;
      creatorFee: string;
      quoteCharged: string;
      tokensOut: string;
      completesCurve: boolean;
      reservesAfter: RawReserves;
    }>;
  }[];
  sell: {
    reserves: RawReserves;
    rates: FeeRates;
    tokensIn: string;
    result: Outcome<{
      quoteFromCurve: string;
      platformFee: string;
      creatorFee: string;
      quoteOut: string;
      reservesAfter: RawReserves;
    }>;
  }[];
  inverse: { reserves: RawReserves; rates: FeeRates; tokensOut: string; result: Outcome<string> }[];
  fee: {
    amount: string;
    rates: FeeRates;
    result: Outcome<{ platform: string; creator: string }>;
  }[];
  params: {
    totalSupply: string;
    curveSupply: string;
    targetQuote: string;
    result: Outcome<{
      virtualTokenReserves: string;
      virtualQuoteReserves: string;
      poolSupply: string;
      graduationQuote: string;
    }>;
  }[];
  poolBuy: {
    reserves: RawPoolReserves;
    rates: PoolFeeRates;
    maxQuoteIn: string;
    result: Outcome<{
      quoteToPool: string;
      lpFee: string;
      platformFee: string;
      creatorFee: string;
      quoteCharged: string;
      tokensOut: string;
      reservesAfter: RawPoolReserves;
    }>;
  }[];
  poolSell: {
    reserves: RawPoolReserves;
    rates: PoolFeeRates;
    tokensIn: string;
    result: Outcome<{
      quoteFromPool: string;
      lpFee: string;
      platformFee: string;
      creatorFee: string;
      quoteOut: string;
      reservesAfter: RawPoolReserves;
    }>;
  }[];
}

type RawPoolReserves = Record<keyof PoolReserves, string>;

const vectors: Vectors = JSON.parse(
  readFileSync(
    new URL("../../../crates/archpad-math/tests/vectors/curve.json", import.meta.url),
    "utf8",
  ),
);

const reserves = (raw: RawReserves): Reserves => ({
  virtualQuote: BigInt(raw.virtualQuote),
  virtualToken: BigInt(raw.virtualToken),
  realQuote: BigInt(raw.realQuote),
  realToken: BigInt(raw.realToken),
});

const rawReserves = (r: Reserves): RawReserves => ({
  virtualQuote: r.virtualQuote.toString(),
  virtualToken: r.virtualToken.toString(),
  realQuote: r.realQuote.toString(),
  realToken: r.realToken.toString(),
});

const poolReserves = (raw: RawPoolReserves): PoolReserves => ({
  quote: BigInt(raw.quote),
  token: BigInt(raw.token),
});

const rawPoolReserves = (r: PoolReserves): RawPoolReserves => ({
  quote: r.quote.toString(),
  token: r.token.toString(),
});

/** Runs `compute` and renders its result in the same shape the vectors use. */
function outcome<T>(compute: () => T): Outcome<T> {
  try {
    return { ok: compute() };
  } catch (error) {
    if (error instanceof MathError) return { err: error.code };
    throw error;
  }
}

describe("golden vectors from archpad-math", () => {
  it("has a meaningful number of cases", () => {
    expect(vectors.buy.length).toBeGreaterThan(500);
    expect(vectors.sell.length).toBeGreaterThan(500);
    expect(vectors.inverse.length).toBeGreaterThan(200);
    expect(vectors.fee.length).toBeGreaterThan(200);
    expect(vectors.params.length).toBeGreaterThan(10);
  });

  it("quoteBuy matches every case", () => {
    for (const c of vectors.buy) {
      const got = outcome(() => {
        const q = quoteBuy(reserves(c.reserves), c.rates, BigInt(c.maxQuoteIn));
        return {
          quoteToCurve: q.quoteToCurve.toString(),
          platformFee: q.fees.platform.toString(),
          creatorFee: q.fees.creator.toString(),
          quoteCharged: q.quoteCharged.toString(),
          tokensOut: q.tokensOut.toString(),
          completesCurve: q.completesCurve,
          reservesAfter: rawReserves(q.reservesAfter),
        };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("quoteSell matches every case", () => {
    for (const c of vectors.sell) {
      const got = outcome(() => {
        const q = quoteSell(reserves(c.reserves), c.rates, BigInt(c.tokensIn));
        return {
          quoteFromCurve: q.quoteFromCurve.toString(),
          platformFee: q.fees.platform.toString(),
          creatorFee: q.fees.creator.toString(),
          quoteOut: q.quoteOut.toString(),
          reservesAfter: rawReserves(q.reservesAfter),
        };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("quoteInForTokensOut matches every case", () => {
    for (const c of vectors.inverse) {
      const got = outcome(() =>
        quoteInForTokensOut(reserves(c.reserves), c.rates, BigInt(c.tokensOut)).toString(),
      );
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("splitFee matches every case", () => {
    for (const c of vectors.fee) {
      const got = outcome(() => {
        const fees = splitFee(BigInt(c.amount), c.rates);
        return { platform: fees.platform.toString(), creator: fees.creator.toString() };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("curveParamsFromTarget matches every case", () => {
    for (const c of vectors.params) {
      const got = outcome(() => {
        const p = curveParamsFromTarget(
          BigInt(c.totalSupply),
          BigInt(c.curveSupply),
          BigInt(c.targetQuote),
        );
        return {
          virtualTokenReserves: p.virtualTokenReserves.toString(),
          virtualQuoteReserves: p.virtualQuoteReserves.toString(),
          poolSupply: poolSupply(p).toString(),
          graduationQuote: graduationQuote(p).toString(),
        };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("poolQuoteBuy matches every case", () => {
    expect(vectors.poolBuy.length).toBeGreaterThan(200);
    for (const c of vectors.poolBuy) {
      const got = outcome(() => {
        const q = poolQuoteBuy(poolReserves(c.reserves), c.rates, BigInt(c.maxQuoteIn));
        return {
          quoteToPool: q.quoteToPool.toString(),
          lpFee: q.fees.lp.toString(),
          platformFee: q.fees.platform.toString(),
          creatorFee: q.fees.creator.toString(),
          quoteCharged: q.quoteCharged.toString(),
          tokensOut: q.tokensOut.toString(),
          reservesAfter: rawPoolReserves(q.reservesAfter),
        };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });

  it("poolQuoteSell matches every case", () => {
    expect(vectors.poolSell.length).toBeGreaterThan(200);
    for (const c of vectors.poolSell) {
      const got = outcome(() => {
        const q = poolQuoteSell(poolReserves(c.reserves), c.rates, BigInt(c.tokensIn));
        return {
          quoteFromPool: q.quoteFromPool.toString(),
          lpFee: q.fees.lp.toString(),
          platformFee: q.fees.platform.toString(),
          creatorFee: q.fees.creator.toString(),
          quoteOut: q.quoteOut.toString(),
          reservesAfter: rawPoolReserves(q.reservesAfter),
        };
      });
      expect(got, JSON.stringify(c)).toEqual(c.result);
    }
  });
});

describe("argument checking", () => {
  const fresh: Reserves = {
    virtualQuote: 30_000_000_000n,
    virtualToken: 1_073_000_000_000_000n,
    realQuote: 0n,
    realToken: 793_100_000_000_000n,
  };
  const rates: FeeRates = { platformBps: 100, creatorBps: 125 };

  it("rejects amounts the chain cannot represent instead of quoting them", () => {
    expect(() => quoteBuy(fresh, rates, -1n)).toThrow(RangeError);
    expect(() => quoteBuy(fresh, rates, 1n << 64n)).toThrow(RangeError);
    expect(() => quoteSell(fresh, rates, -1n)).toThrow(RangeError);
    expect(() => quoteBuy({ ...fresh, realToken: -1n }, rates, 1_000n)).toThrow(RangeError);
  });

  it("rejects fee rates that are not whole basis points", () => {
    expect(() => splitFee(1_000n, { platformBps: 1.5, creatorBps: 0 })).toThrow(RangeError);
    expect(() => splitFee(1_000n, { platformBps: -1, creatorBps: 0 })).toThrow(RangeError);
  });
});
